$stats=[];foreach(['documents','cases','institutions','research_users','institutional_subscriptions','subscriptions'] as $table){$stats[$table]=(int)$pdo->query("SELECT COUNT(*) FROM {$table}")->fetchColumn();}$published=(int)$pdo->query('SELECT (SELECT COUNT(*) FROM documents WHERE is_published=1)+(SELECT COUNT(*) FROM cases WHERE is_published=1)+(SELECT COUNT(*) FROM institutions WHERE is_published=1)')->fetchColumn();$versions=(int)$pdo->query('SELECT COUNT(*) FROM document_versions')->fetchColumn();$inquiries=(int)$pdo->query("SELECT COUNT(*) FROM institutional_subscriptions WHERE status='inquiry'")->fetchColumn();$logs=$pdo->query('SELECT a.*,u.name user_name FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 8')->fetchAll();$recent=$pdo->query("SELECT d.id,d.title,d.legal_status,d.is_published,d.updated_at,COALESCE(c.name,UPPER(d.regime_key),'Regional') scope FROM documents d LEFT JOIN countries c ON c.id=d.country_id ORDER BY d.updated_at DESC LIMIT 5")->fetchAll();
